# Example usage of ConditionedViT with Adaptive Layer Normalization\n\nimport torch\nfrom vision_transformer import ConditionedViT\n\n# Define modalities and body parts for medical imaging\nmodalities = ['CT', 'XRay', 'MRI', 'Ultrasound']\nbody_parts = ['Chest', 'Brain', 'Abdomen', 'Pelvis']\n\n# Create conditioning-aware ViT\nmodel = ConditionedViT(\n    img_size=224,\n    patch_size=16,\n    embed_dim=768,\n    depth=12,\n    num_heads=12,\n    use_conditioning=True,\n    modalities=modalities,\n    body_parts=body_parts,\n    conditioning_dim=128,\n)\n\n# Example forward pass\nbatch_size = 4\nimg_tensor = torch.randn(batch_size, 3, 224, 224)\n\n# Each sample in the batch can have different modality-body part combinations\nmodality_batch = ['CT', 'XRay', 'MRI', 'CT']\nbody_part_batch = ['Chest', 'Chest', 'Brain', 'Abdomen']\n\n# Forward pass with conditioning\noutput = model(\n    img_tensor, \n    modality=modality_batch, \n    body_part=body_part_batch\n)\n\nprint(f\"Output shape: {output.shape}\")  # Should be [4, 768] for classification token\n\n# Example for inference mode\nmodel.eval()\nwith torch.no_grad():\n    features = model.forward_features(\n        img_tensor,\n        modality=modality_batch,\n        body_part=body_part_batch\n    )\n    \nprint(f\"CLS token features shape: {features['x_norm_clstoken'].shape}\")\nprint(f\"Patch token features shape: {features['x_norm_patchtokens'].shape}\")\nprint(f\"Conditioning embedding shape: {features['conditioning_emb'].shape}\")\n\n# Example without conditioning (backward compatibility)\nmodel_standard = ConditionedViT(\n    img_size=224,\n    patch_size=16,\n    embed_dim=768,\n    depth=12,\n    num_heads=12,\n    use_conditioning=False,  # Standard ViT behavior\n)\n\n# Standard forward pass\noutput_standard = model_standard(img_tensor)\nprint(f\"Standard output shape: {output_standard.shape}\")\n